                    queue = [(r, col)]
                    visited[r][col] = True
                    while queue:
                        cr, cc = queue.pop(0)
                        component.append((cr, cc))
                        # Check neighbors
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[nr][nc] == c:
